# Записывает адреса разделам без адреса и убирает три адреса-обхода закрытой
# регистрации (account/register, account/forgotten, account/simpleregister).
# Всё, что сделано, пишется в таблицу oc_chpu_changes — по ней работает откат
# (3-otkat.sh). Эта же таблица не даёт запустить команду дважды: второй запуск
# пишет STOP и ничего не трогает. Если адреса не прочитались — STOP до любых
# изменений. Проверено на MariaDB 10.11 с копией таблиц движка: запись,
# повторный запуск, откат до байта, сбой чтения.
( cd /var/www/u2934771/data/www/stroigeroi.ru || exit 1; php -r 'mysqli_report(MYSQLI_REPORT_OFF); include "config.php"; $m = @new mysqli(DB_HOSTNAME, DB_USERNAME, DB_PASSWORD, DB_DATABASE, (int)DB_PORT); if ($m->connect_error) { echo "DB: ", $m->connect_error, "\n"; exit(1); } $m->set_charset("utf8"); $q = function ($s) use ($m) { $r = $m->query(str_replace("{p}", DB_PREFIX, $s)); if (!$r) { echo "SQL: ", $m->error, "\n"; return false; } if ($r === true) return array(); $a = array(); while ($x = $r->fetch_row()) $a[] = $x; return $a; }; $e = function ($s) use ($m) { return "\"" . $m->real_escape_string($s) . "\""; }; $lg = $q("SELECT language_id FROM {p}language WHERE code = (SELECT value FROM {p}setting WHERE `key` = \"config_language\" AND store_id = 0 LIMIT 1) LIMIT 1"); $lang = $lg ? (int)$lg[0][0] : 1; $L = explode(",", "a,b,v,g,d,e,zh,z,i,y,k,l,m,n,o,p,r,s,t,u,f,h,c,ch,sh,sch,,y,,e,yu,ya"); $u = function ($c) { return chr(0xC0 | ($c >> 6)) . chr(0x80 | ($c & 0x3F)); }; $tr = array($u(0x451) => "e", $u(0x401) => "e"); foreach ($L as $i => $v) { $tr[$u(0x430 + $i)] = $v; $tr[$u(0x410 + $i)] = $v; } $slug = function ($t) use ($tr) { $s = trim(preg_replace("/[^a-z0-9]+/", "-", strtolower(strtr($t, $tr))), "-"); if (strlen($s) > 90) { $s = substr($s, 0, 90); $p = strrpos($s, "-"); if ($p !== false) $s = substr($s, 0, $p); } return $s; }; $all = $q("SELECT LOWER(keyword), query FROM {p}seo_url WHERE store_id = 0 AND keyword <> \"\""); $rows = $q("SELECT c.category_id, IFNULL((SELECT name FROM {p}category_description WHERE category_id = c.category_id AND language_id = $lang), \"\") FROM {p}category c WHERE c.status = 1 AND NOT EXISTS (SELECT 1 FROM {p}seo_url s WHERE s.store_id = 0 AND s.keyword <> \"\" AND s.query = CONCAT(\"category_id=\", c.category_id)) ORDER BY c.parent_id <> 0, c.parent_id, c.category_id"); if ($all === false || $rows === false) { echo "STOP: could not read addresses, nothing changed\n"; exit(1); } if ($q("CREATE TABLE {p}chpu_changes (action VARCHAR(8) NOT NULL, seo_url_id INT NULL, store_id INT NOT NULL, language_id INT NOT NULL, query VARCHAR(255) NOT NULL, keyword VARCHAR(255) NOT NULL) DEFAULT CHARSET=utf8") === false) { echo "STOP: table ", DB_PREFIX, "chpu_changes exists - already done, nothing changed\n"; exit(1); } $taken = array(); foreach ($all as $r) $taken[$r[0]] = $r[1]; $added = 0; foreach ($rows as $r) { $base = $slug($r[1]); if ($base === "") $base = "razdel"; $kw = $base; $n = 1; while (isset($taken[$kw])) { $n++; $kw = $base . "-" . $n; } $taken[$kw] = "category_id=" . $r[0]; $qs = $e("category_id=" . (int)$r[0]); if ($q("INSERT INTO {p}chpu_changes (action, store_id, language_id, query, keyword) VALUES (\"added\", 0, $lang, $qs, " . $e($kw) . ")") !== false && $q("INSERT INTO {p}seo_url (store_id, language_id, query, keyword) VALUES (0, $lang, $qs, " . $e($kw) . ")") !== false) $added++; } $routes = "\"account/register\", \"account/forgotten\", \"account/simpleregister\""; $q("INSERT INTO {p}chpu_changes (action, seo_url_id, store_id, language_id, query, keyword) SELECT \"removed\", seo_url_id, store_id, language_id, query, keyword FROM {p}seo_url WHERE query IN ($routes)"); $gone = $q("SELECT keyword FROM {p}chpu_changes WHERE action = \"removed\"") ?: array(); $q("DELETE s FROM {p}seo_url s JOIN {p}chpu_changes c ON c.action = \"removed\" AND c.seo_url_id = s.seo_url_id"); $c = $q("SELECT COUNT(*), SUM(EXISTS(SELECT 1 FROM {p}seo_url s WHERE s.store_id = 0 AND s.keyword <> \"\" AND s.query = CONCAT(\"category_id=\", t.category_id))) FROM {p}category t WHERE t.status = 1") ?: array(array("?", "?")); echo "added: $added of ", count($rows), "\n"; echo "removed: "; foreach ($gone as $g) echo $g[0], " "; echo "\n"; echo "categories: ", $c[0][0], " / ", $c[0][1], "\n";' || exit 1; for u in elektrika-i-svet osveschenie; do echo "== /$u: $(curl -s -w ' %{http_code}' "https://stroigeroi.ru/$u" | grep -oE '<title>[^<]*| [0-9]{3}$' | tr "\n" " ")"; done; for u in create-account forgot-password "index.php?route=account/register"; do echo "$u: $(curl -s -o /dev/null -w '%{http_code}' "https://stroigeroi.ru/$u")"; done )
